-- Nicknames for the playerbots. GENERATED - edit
-- linux-port/overlays/playerbot/data/bot_names_iwakura.txt or bot_names_edi.txt
-- (the Polish pool), or a language's own data/bot_names_<code>.txt, and re-run
-- linux-port/overlays/playerbot/tools/generate_bot_names.py.
--
-- Applied by mariadb/playerbot/apply.sh after the seed, guarded by
-- @playerbot_human_names, which apply.sh sets from M2_PLAYERBOT_HUMAN_NAMES:
--
--   1        every bot wears a name from its world's pool (default)
--   0        keep existing names, except explicitly retired managed names
--   restore  put the seed names back and forget the renames
--
-- The pools, by language:
--   pl 162886b10d3e: 3840 names, tr e750e1abeef5: 3528 names
-- Every other language deals the Polish one. A world deals from the pool
-- common.playerbot_name_world names: decided while no bot wears a pool name
-- yet, from @playerbot_name_language (apply.sh: M2_PLAYERBOT_NAME_LANGUAGE,
-- the launcher's game language), kept from the first naming on, and 'pl' for
-- a world whose bots were named before there were pools. It moves only when the
-- operator asks for another language there (requested, the panel's switch);
-- then every bot that still wears a pool name of another language takes one of
-- the new pool, and a bot renamed by hand or a companion keeps its own.
--
-- Only a character whose account login is playerbot_NNN is ever touched: no
-- character of a person is reachable from here. A bot the operator renamed
-- by hand - its name is neither the one this table gave it nor its seed name
-- - is somebody's deliberate choice and keeps it, through every pool version;
-- its name is never dealt to another bot either. Names go out by PID to the
-- bots that have none from the pool yet; a bot that has one keeps it through
-- every later list (common.playerbot_name_history.pool_version says which list
-- it came from), so a new list names a new world, a grown cohort and a bot
-- still on its seed name, and renames nobody.
-- Explicitly retired managed nicknames are the exception: only their owners
-- receive a free replacement, even when naming new bots is disabled.
-- The seed name stays in that table, which is what makes 'restore' possible.
-- Each kingdom deals from its own share of the list (player_index.empire says
-- whose a bot is), so Shinsoo and Jinno get written names and not the v2/v3
-- copies of Chunjo's.

-- A temporary table needs a default database and the client this is fed to has
-- selected none; playerbots_seed.sql opens the same way and for the same
-- reason. Every other table is named in full.
USE player;

CREATE TABLE IF NOT EXISTS common.playerbot_name_history (
    pid          INT UNSIGNED NOT NULL,
    seed_name    VARCHAR(24) NOT NULL,
    human_name   VARCHAR(24) NOT NULL,
    renamed_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (pid),
    KEY human_name (human_name)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;
-- A world renamed by the first pool has no version column yet.
ALTER TABLE common.playerbot_name_history
    ADD COLUMN IF NOT EXISTS pool_version VARCHAR(16) NOT NULL DEFAULT '';
-- Which written list a dealt name came from ('iwakura', 'edi'); '' for a name
-- dealt before 8 October, all of them Iwakura's.
ALTER TABLE common.playerbot_name_history
    ADD COLUMN IF NOT EXISTS name_source VARCHAR(8) NOT NULL DEFAULT '';
-- Which language's pool a dealt name came from ('pl', 'tr'); '' for a name
-- dealt before 21 October, all of them the Polish pool's.
ALTER TABLE common.playerbot_name_history
    ADD COLUMN IF NOT EXISTS name_language VARCHAR(8) NOT NULL DEFAULT '';

-- The world's language for its bots' names, one row. language is the pool it
-- deals from; asked what @playerbot_name_language said when it was decided;
-- requested a language the operator asked to move to at the next start.
CREATE TABLE IF NOT EXISTS common.playerbot_name_world (
    singleton   TINYINT UNSIGNED NOT NULL PRIMARY KEY,
    language    VARCHAR(8) NOT NULL,
    asked       VARCHAR(8) NOT NULL DEFAULT '',
    requested   VARCHAR(8) NOT NULL DEFAULT '',
    decided_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    switched_at TIMESTAMP NULL DEFAULT NULL
) ENGINE=MyISAM DEFAULT CHARSET=latin1;
-- The pools this release carries, for the panel's switch.
CREATE TABLE IF NOT EXISTS common.playerbot_name_pools (
    language VARCHAR(8) NOT NULL PRIMARY KEY,
    version  VARCHAR(16) NOT NULL,
    names    INT UNSIGNED NOT NULL,
    source   VARCHAR(32) NOT NULL DEFAULT ''
) ENGINE=MyISAM DEFAULT CHARSET=latin1;

SET @playerbot_human_names = IFNULL(@playerbot_human_names, '1');
SET @playerbot_name_language = LOWER(IFNULL(@playerbot_name_language, ''));
SET @playerbot_name_language = IF(@playerbot_name_language REGEXP '^[a-z][a-z]$',
                                  @playerbot_name_language, '');

-- A hand-renamed bot keeps its current safe name. Scrub a retired former
-- pool name from its ledger without making 'restore' overwrite that choice.
-- The original bot* seed remains available; no character or item is deleted.
UPDATE common.playerbot_name_history AS h
  JOIN player.player AS p ON p.id = h.pid
  JOIN account.account AS a ON a.id = p.account_id
   SET h.human_name = h.seed_name
 WHERE a.login REGEXP '^playerbot_[0-9]+$'
   AND LEFT(h.seed_name, 3) = 'bot'
   AND ((SHA2(LOWER(LEFT(h.human_name, 8)), 256) = '7c80560ca077309a383ab7f101cf7e3776ae2e12c9de7ae88e808ccaaa759626' AND SUBSTRING(LOWER(h.human_name), 9) REGEXP '^(v?[0-9]+)?$'))
   AND NOT ((SHA2(LOWER(LEFT(p.name, 8)), 256) = '7c80560ca077309a383ab7f101cf7e3776ae2e12c9de7ae88e808ccaaa759626' AND SUBSTRING(LOWER(p.name), 9) REGEXP '^(v?[0-9]+)?$'));

-- --------------------------------------------------------------------------
-- restore: the seed name goes back, and only onto a character that still
-- wears the name this table handed it. A bot renamed again by hand afterwards
-- is somebody's deliberate choice and is left alone.
-- --------------------------------------------------------------------------
UPDATE player.player AS p
  JOIN common.playerbot_name_history AS h ON h.pid = p.id
   SET p.name = h.seed_name
 WHERE @playerbot_human_names = 'restore'
   AND BINARY p.name = BINARY h.human_name;

DELETE FROM common.playerbot_name_history
 WHERE @playerbot_human_names = 'restore';

SELECT CONCAT('playerbot names: restored ', ROW_COUNT(), ' seed name(s)')
       AS playerbot_names_note
  FROM DUAL
 WHERE @playerbot_human_names = 'restore';

-- --------------------------------------------------------------------------
-- The pools: each language's names as written, shuffled once and cut into a
-- share per kingdom, then each share again with 2/v2 and 3/v3 behind the names
-- and the whole list with v4.. after that, 3000 names a kingdom in
-- every pool (18000 rows in all). A name is once in its pool; two pools
-- may hold the same one (Said kept names of the Polish lists for Turkish).
-- --------------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS playerbot_name_langs;
CREATE TEMPORARY TABLE playerbot_name_langs (
    lang    VARCHAR(8) NOT NULL PRIMARY KEY,
    version VARCHAR(16) NOT NULL,
    names   INT UNSIGNED NOT NULL,
    source  VARCHAR(32) NOT NULL DEFAULT ''
) ENGINE=MEMORY DEFAULT CHARSET=latin1;
INSERT INTO playerbot_name_langs (lang, version, names, source) VALUES
    ('pl','162886b10d3e',9000,'edi,iwakura'),
    ('tr','e750e1abeef5',9000,'said');

DROP TEMPORARY TABLE IF EXISTS playerbot_name_pool;
CREATE TEMPORARY TABLE playerbot_name_pool (
    n      INT UNSIGNED NOT NULL PRIMARY KEY,
    empire TINYINT UNSIGNED NOT NULL,
    name   VARCHAR(24) NOT NULL,
    source VARCHAR(8) NOT NULL DEFAULT '',
    lang   VARCHAR(8) NOT NULL DEFAULT 'pl',
    UNIQUE KEY name (lang, name),
    KEY empire (lang, empire, n)
) ENGINE=MEMORY DEFAULT CHARSET=latin1;

