DELETE FROM common.playerbot_name_pools;
INSERT INTO common.playerbot_name_pools (language, version, names, source)
SELECT lang, version, names, source FROM playerbot_name_langs;

-- --------------------------------------------------------------------------
-- The world's language, decided while no bot of it wears a pool name yet
-- (no history row that is not a companion's own) and kept from the first
-- naming on. A world whose bots wore names before this table existed was
-- named from the Polish pool and keeps it. A world nobody is named in yet -
-- a fresh one, names switched off, a 'restore', a database whose player
-- tables were made anew under an old common - takes the language apply.sh
-- handed in, when this release has a pool for it, and the Polish pool
-- otherwise ("en" deals Polish names until somebody writes an English list,
-- and the world keeps them after that unless the operator asks).
-- --------------------------------------------------------------------------
SET @playerbot_name_named = (SELECT COUNT(*) FROM common.playerbot_name_history
                              WHERE pool_version <> 'sidekick');
SET @playerbot_name_offered = (SELECT COUNT(*) FROM playerbot_name_langs
                                WHERE lang = @playerbot_name_language);
INSERT INTO common.playerbot_name_world (singleton, language, asked)
SELECT 1,
       CASE WHEN @playerbot_name_named > 0 THEN 'pl'
            WHEN @playerbot_name_offered > 0 THEN @playerbot_name_language
            ELSE 'pl' END,
       @playerbot_name_language
  FROM DUAL
    ON DUPLICATE KEY UPDATE
       language = IF(@playerbot_name_named > 0, language, VALUES(language)),
       asked = IF(@playerbot_name_named > 0, asked, VALUES(asked)),
       decided_at = IF(@playerbot_name_named > 0, decided_at, NOW());

-- The operator's request, at the start after it: only with names on, and only
-- to a pool this release carries; a request for one it does not is cleared.
UPDATE common.playerbot_name_world AS w
  JOIN playerbot_name_langs AS l ON l.lang = w.requested
   SET w.language = w.requested, w.requested = '', w.switched_at = NOW()
 WHERE w.singleton = 1 AND @playerbot_human_names = '1';
SET @playerbot_name_switched = ROW_COUNT();
SELECT CONCAT('playerbot names: WARNING the requested language ', requested,
              ' has no pool in this release; request cleared') AS playerbot_names_note
  FROM common.playerbot_name_world
 WHERE singleton = 1 AND requested <> ''
   AND requested NOT IN (SELECT lang FROM playerbot_name_langs);
UPDATE common.playerbot_name_world
   SET requested = ''
 WHERE singleton = 1 AND requested <> ''
   AND requested NOT IN (SELECT lang FROM playerbot_name_langs);

-- The pool this start deals from. A world's pool that a later release no
-- longer carried would deal the Polish one, and rename nobody for it
-- (@playerbot_name_settled 0): moving a world off its pool is the request's.
SET @playerbot_name_pool = IFNULL((SELECT language FROM common.playerbot_name_world
                                    WHERE singleton = 1), 'pl');
SET @playerbot_name_settled = (SELECT COUNT(*) FROM playerbot_name_langs
                                WHERE lang = @playerbot_name_pool);
SET @playerbot_name_pool = IF(@playerbot_name_settled > 0, @playerbot_name_pool, 'pl');
SET @playerbot_pool_version = (SELECT version FROM playerbot_name_langs
                                WHERE lang = @playerbot_name_pool);

SELECT CONCAT('playerbot names: the world deals the ', @playerbot_name_pool,
              ' pool, version ', @playerbot_pool_version,
              IF(@playerbot_name_switched > 0, ' (switched at the operator''s request)', ''))
       AS playerbot_names_note
  FROM DUAL
 WHERE @playerbot_human_names = '1';

-- A bot of another pool that already wears a name of this one keeps it and is
-- this pool's: Said kept Furkan and DarkSpear for Turkish, and a switch must
-- not take a name from one bot only to deal it to another.
UPDATE common.playerbot_name_history AS h
  JOIN player.player AS p ON p.id = h.pid
  JOIN account.account AS a ON a.id = p.account_id
  JOIN playerbot_name_pool AS np ON np.lang = @playerbot_name_pool AND np.name = p.name
   SET h.name_language = @playerbot_name_pool
 WHERE @playerbot_human_names = '1' AND @playerbot_name_settled > 0
   AND IF(h.name_language = '', 'pl', h.name_language) <> @playerbot_name_pool
   AND LEFT(h.seed_name, 3) = 'bot' AND a.login REGEXP '^playerbot_[0-9]+$'
                 AND h.pool_version <> 'sidekick' AND BINARY p.name = BINARY h.human_name;

-- --------------------------------------------------------------------------
-- Who gets one, and which. Every bot without a name from the pool - no
-- history row at all - waits, numbered by PID within its kingdom; every pool
-- name of that kingdom's share not worn by anybody who is not waiting is free,
-- numbered by its place in the share; the two are joined on kingdom and
-- number. One statement, stable: the first free name goes to the lowest
-- waiting PID.
--
-- "Not worn by anybody who is not waiting" is the whole point of the free
-- side. It used to exclude only people's characters, on the argument that
-- every bot was being renamed at once - which was never true of the other way
-- a bot comes to wait: a cohort seeded later. 2.0.8 switched the kingdoms on
-- and seeded a thousand Shinsoo and Jinno bots into worlds whose Chunjo bots
-- were already named; those thousand were numbered from one and dealt the
-- names of the first thousand Chunjo bots, so a world had two of each. Every
-- settled bot - a history row of any version - keeps the name it wears off
-- the free list, and so does a person's character. A later list lands its
-- names in other kingdoms' shares than the earlier one did, which is why the
-- free side asks who wears a name and not which share it came from.
-- player.name is indexed, not unique, so nothing else would have caught it.
--
-- A bot that wears a name of another language's pool waits too, once the
-- world has moved to this pool at the operator's request (and only a bot
-- that still wears its pool name: a name given by hand, a companion's, stays).
-- Its seed name stays in the history, so 'restore' still puts that back.
-- --------------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS playerbot_name_plan;
CREATE TEMPORARY TABLE playerbot_name_plan (
    pid        INT UNSIGNED NOT NULL PRIMARY KEY,
    seed_name  VARCHAR(24) NOT NULL,
    human_name VARCHAR(24) NOT NULL,
    source     VARCHAR(8) NOT NULL DEFAULT '',
    UNIQUE KEY human_name (human_name)
) ENGINE=MEMORY DEFAULT CHARSET=latin1;

INSERT INTO playerbot_name_plan (pid, seed_name, human_name, source)
SELECT waiting.pid, waiting.seed_name, free.name, free.source
  FROM (
        SELECT p.id AS pid,
               IFNULL(h.seed_name, p.name) AS seed_name,
               (((SHA2(LOWER(LEFT(p.name, 8)), 256) = '7c80560ca077309a383ab7f101cf7e3776ae2e12c9de7ae88e808ccaaa759626' AND SUBSTRING(LOWER(p.name), 9) REGEXP '^(v?[0-9]+)?$')) AND h.pid IS NOT NULL
                AND LEFT(h.seed_name, 3) = 'bot'
                AND a.login REGEXP '^playerbot_[0-9]+$') AS retired,
               CASE WHEN pi.empire IN (1, 2, 3) THEN pi.empire ELSE 2 END AS empire,
               ROW_NUMBER() OVER (
                   PARTITION BY CASE WHEN pi.empire IN (1, 2, 3) THEN pi.empire ELSE 2 END
                   ORDER BY p.id) AS rn
          FROM player.player AS p
          JOIN account.account AS a ON a.id = p.account_id
          LEFT JOIN player.player_index AS pi ON pi.id = p.account_id
          LEFT JOIN common.playerbot_name_history AS h ON h.pid = p.id
         WHERE LEFT(a.login, 10) = 'playerbot_'
           -- A never-named bot or an explicitly retired managed nickname.
           -- Other history rows keep their names - the pool's, or a
           -- person's choice made over it ("bot ADAM dostal ode mnie miecz
           -- +9, rano juz nie bylo bota o tym nicku" - the first version
           -- renamed it with the rest).
           AND (h.pid IS NULL OR
                (((SHA2(LOWER(LEFT(p.name, 8)), 256) = '7c80560ca077309a383ab7f101cf7e3776ae2e12c9de7ae88e808ccaaa759626' AND SUBSTRING(LOWER(p.name), 9) REGEXP '^(v?[0-9]+)?$')) AND LEFT(h.seed_name, 3) = 'bot'
                 AND a.login REGEXP '^playerbot_[0-9]+$') OR
                (@playerbot_human_names = '1' AND @playerbot_name_settled > 0
                 AND IF(h.name_language = '', 'pl', h.name_language) <> @playerbot_name_pool
                 AND LEFT(h.seed_name, 3) = 'bot' AND a.login REGEXP '^playerbot_[0-9]+$'
                 AND h.pool_version <> 'sidekick' AND BINARY p.name = BINARY h.human_name))
       ) AS waiting
  JOIN (
        SELECT np.name, np.empire, np.source,
               ROW_NUMBER() OVER (PARTITION BY np.empire ORDER BY np.n) AS rn
          FROM playerbot_name_pool AS np
         WHERE np.lang = @playerbot_name_pool
           AND NOT EXISTS (SELECT 1
                             FROM player.player AS px
                             JOIN account.account AS ax ON ax.id = px.account_id
                             LEFT JOIN common.playerbot_name_history AS hx ON hx.pid = px.id
                            WHERE px.name = np.name
                              AND NOT (@playerbot_human_names = '1'
                                       AND LEFT(ax.login, 10) = 'playerbot_' AND hx.pid IS NULL))
       ) AS free
    ON free.empire = waiting.empire AND free.rn = waiting.rn
 WHERE @playerbot_human_names = '1' OR waiting.retired;

INSERT INTO common.playerbot_name_history (pid, seed_name, human_name, pool_version, name_source,
                                           name_language, renamed_at)
SELECT pid, seed_name, human_name, @playerbot_pool_version, source, @playerbot_name_pool, NOW()
  FROM playerbot_name_plan
    ON DUPLICATE KEY UPDATE human_name = VALUES(human_name),
                            pool_version = VALUES(pool_version),
                            name_source = VALUES(name_source),
                            name_language = VALUES(name_language),
                            renamed_at = VALUES(renamed_at);

UPDATE player.player AS p
  JOIN playerbot_name_plan AS pl ON pl.pid = p.id
   SET p.name = pl.human_name;

-- HAVING, not WHERE: the aggregate returns one row over an empty plan, and a
-- 'restore' run would otherwise report "gave 0" straight after "restored 2500".
SELECT CONCAT('playerbot names: gave ', COUNT(*), ' bot(s) a name from the ',
              @playerbot_name_pool, ' pool ', @playerbot_pool_version)
       AS playerbot_names_note
  FROM playerbot_name_plan
HAVING @playerbot_human_names = '1';

-- A cohort larger than its kingdom's share is the one way this runs out; say
-- so rather than leaving an operator to wonder why some bots kept their old
-- names. A hand-renamed bot is not counted: it was left alone on purpose.
SELECT CONCAT('playerbot names: WARNING ', COUNT(*),
              ' bot(s) got no name - a kingdom used up its 3000 names')
       AS playerbot_names_note
  FROM player.player AS p
  JOIN account.account AS a ON a.id = p.account_id
  LEFT JOIN common.playerbot_name_history AS h ON h.pid = p.id
 WHERE @playerbot_human_names = '1'
   AND LEFT(a.login, 10) = 'playerbot_'
   AND h.pid IS NULL
HAVING COUNT(*) > 0;

-- The hand-renamed, so the operator sees them counted rather than wondering
-- why a bot kept a name that is on no list.
SELECT CONCAT('playerbot names: ', COUNT(*),
              ' bot(s) renamed by hand keep their names')
       AS playerbot_names_note
  FROM player.player AS p
  JOIN account.account AS a ON a.id = p.account_id
  JOIN common.playerbot_name_history AS h ON h.pid = p.id
 WHERE @playerbot_human_names = '1'
   AND LEFT(a.login, 10) = 'playerbot_'
   AND BINARY p.name <> BINARY h.human_name
   AND BINARY p.name <> BINARY h.seed_name
HAVING COUNT(*) > 0;

DROP TEMPORARY TABLE IF EXISTS playerbot_name_plan;
DROP TEMPORARY TABLE IF EXISTS playerbot_name_pool;
DROP TEMPORARY TABLE IF EXISTS playerbot_name_langs;
